/**
 * Pure helpers for `npm run db:types` (scripts/db/gen-types.ts). Spec: tests/db-types.test.ts.
 */
export const TYPES_HEADER =
  "// GENERATED by `npm run db:types` from the live database schema (Supabase Management API).\n" +
  "// Do not edit by hand; re-run after a migration. `npm run db:types -- --check` exits 1 on drift.\n\n";

const norm = (s: string) => s.replace(/\r\n/g, "\n").replace(/\n+$/, "");

/** True when the committed file and freshly generated types differ (line endings ignored). */
export function typesDrift(committed: string, fresh: string): boolean {
  return norm(committed) !== norm(fresh);
}

export function buildTypesFile(types: string): string {
  return TYPES_HEADER + norm(types) + "\n";
}
